<script setup>
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { adminBlindboxes, createBlindbox, changeBlindboxStatus, adminPrizes } from '../../api/blindbox'
import PageTitle from '../../components/PageTitle.vue'
const rows=ref([]),loading=ref(false),dialog=ref(false),prizeDialog=ref(false),target=ref(null),form=ref({name:'',albumId:'',price:'',totalCount:1,description:'',prizesText:'[]'}),prize=ref({prizeName:'',prizeLevel:1,probability:1,imageUrl:'',description:''})
async function load(){loading.value=true;try{const p=await adminBlindboxes({current:1,size:50});rows.value=p?.records||[]}finally{loading.value=false}}
async function save(){let prizes;try{prizes=JSON.parse(form.value.prizesText);if(!Array.isArray(prizes)||!prizes.length)throw new Error()}catch{return ElMessage.error('奖品必须是有效且非空的 JSON 数组')};const f=form.value;await createBlindbox({name:f.name,albumId:Number(f.albumId),price:Number(f.price),totalCount:Number(f.totalCount),description:f.description||null,prizes});ElMessage.success('盲盒已创建');dialog.value=false;load()}
async function toggle(row){await changeBlindboxStatus(row.id,Number(row.status)===1?0:1);ElMessage.success('状态已更新');load()}
async function addPrize(){await adminPrizes(target.value.id,{...prize.value,probability:Number(prize.value.probability),prizeLevel:Number(prize.value.prizeLevel),imageUrl:prize.value.imageUrl||null,description:prize.value.description||null});prizeDialog.value=false;ElMessage.success('奖品已添加')}
onMounted(load)
</script>
<template><div class="admin-page"><PageTitle eyebrow="MYSTERY EDITION" title="盲盒管理"/><div class="toolbar"><el-button type="primary" @click="dialog=true">新建盲盒</el-button><el-button @click="load">刷新</el-button></div><el-table v-loading="loading" :data="rows"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="name" label="名称"/><el-table-column prop="albumId" label="关联专辑"/><el-table-column prop="price" label="价格"/><el-table-column prop="remainCount" label="剩余库存"/><el-table-column prop="status" label="状态"><template #default="{row}">{{Number(row.status)===1?'上架':'下架'}}</template></el-table-column><el-table-column label="操作" width="220"><template #default="{row}"><el-button text @click="toggle(row)">{{Number(row.status)===1?'下架':'上架'}}</el-button><el-button text @click="target=row;prizeDialog=true">添加奖品</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" title="创建盲盒" width="min(700px,94vw)"><el-form label-position="top"><div class="form-grid"><el-form-item label="盲盒名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="关联专辑 ID"><el-input v-model="form.albumId" type="number"/></el-form-item><el-form-item label="价格"><el-input v-model="form.price" type="number"/></el-form-item><el-form-item label="总库存"><el-input v-model="form.totalCount" type="number"/></el-form-item><el-form-item label="描述" class="span-2"><el-input v-model="form.description"/></el-form-item><el-form-item label="奖品配置 JSON（字段：prizeName、prizeLevel、probability、imageUrl、description）" class="span-2"><el-input v-model="form.prizesText" type="textarea" :rows="7"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">创建</el-button></template></el-dialog><el-dialog v-model="prizeDialog" title="添加奖品"><el-form label-position="top"><el-form-item label="奖品名称"><el-input v-model="prize.prizeName"/></el-form-item><el-form-item label="稀有度"><el-input v-model="prize.prizeLevel" type="number"/></el-form-item><el-form-item label="概率"><el-input v-model="prize.probability" type="number"/></el-form-item><el-form-item label="图片 URL"><el-input v-model="prize.imageUrl"/></el-form-item><el-form-item label="说明"><el-input v-model="prize.description"/></el-form-item></el-form><template #footer><el-button @click="prizeDialog=false">取消</el-button><el-button type="primary" @click="addPrize">添加</el-button></template></el-dialog></div></template>
